import heapq
from typing import Dict, List, Mapping, Optional, Set, Tuple


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits:
        raise KeyError(src)
    if dst not in limits:
        raise KeyError(dst)
    if src == dst:
        raise ValueError("src and dst cannot be the same")

    best: Dict[str, Tuple[int, int]] = {src: (10**18, 0)}
    predecessor: Dict[str, Optional[str]] = {src: None}
    pq: List[Tuple[int, int, str]] = [(-10**18, 0, src)]
    visited: Set[str] = set()

    while pq:
        neg_cap, path_len, current = heapq.heappop(pq)
        capacity = -neg_cap
        if current in visited:
            continue
        visited.add(current)
        if current == dst:
            path: List[str] = []
            node: Optional[str] = dst
            while node is not None:
                path.append(node)
                node = predecessor.get(node)
            path.reverse()
            return (capacity, path)
        for neighbor, edge_limit in sorted(limits.get(current, {}).items()):
            if neighbor in visited:
                continue
            new_capacity = min(capacity, edge_limit)
            new_path_len = path_len + 1
            old = best.get(neighbor)
            if old is None or new_capacity > old[0] or (new_capacity == old[0] and new_path_len < old[1]):
                best[neighbor] = (new_capacity, new_path_len)
                predecessor[neighbor] = current
                heapq.heappush(pq, (-new_capacity, new_path_len, neighbor))
    return None
